            piece(parent, "Pennant", vector(1.25, .95, .15), vector(index * 3.7, height, z),
                bunting[index % #bunting + 1], material.Fabric, false, nil, CFrame.Angles(0, 0, index * -.025))
            if index < 7 then
                local from = vector(index * 3.7, height + .44, z)
