 if not nextBag then notify(p, "You already own the largest bag."); return end
 if d.Coins < nextBag.Cost then notify(p, "Need " .. nextBag.Cost .. " coins for " .. nextBag.Name .. "."); return end
 d.Coins -= nextBag.Cost
 d.Bag += 1
